"""Author source-linked camp dossiers for the canonical catalogue bridge."""
import json
from pathlib import Path
from collections import Counter

ROOT = Path(__file__).resolve().parents[1]
CHECKED = '2026-10-04'
P = []
def add(slug, name, country, iso, place, themes, formats, age, language,
        programme, dates, price, housing, mat, osc, why, questions, sources,
        status='next_unannounced', priority=None, confirmed=None, sessions=None):
    P.append(dict(id='CP%03d' % (len(P)+1), slug=slug, provider=name, country=country,
        iso=iso, place=place, themes=themes.split(','), formats=formats.split(','), age=age,
        language=language, confirmed_instruction_languages=confirmed or [], programme=programme,
        timing=dict(status=status, label=dates, sessions=sessions or []), price=price,
        accommodation=housing, family_fit=dict(matvey=dict(status=mat[0],detail=mat[1]),
        oscar=dict(status=osc[0],detail=osc[1])), editorial_reason=why,
        shortlist=priority or [], questions=questions, sources=[dict(title=t,url=u,checked=CHECKED) for t,u in sources],
        checked=CHECKED))
def src(t,u): return (t,u)
def fit(s,t): return (s,t)

